def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        nanoseconds = int(nanoseconds)
    except ValueError:
        raise ValueError("nanoseconds must be an integer")
    if tz is not None and not isinstance(tz, datetime.tzinfo):
        raise ValueError("tz must be a datetime.tzinfo object")
    if nanoseconds < 0 or nanoseconds >= 24 * 60 * 60 * 1000000000:
        raise ValueError("nanoseconds must be a valid time")
    if tz is not None:
        return datetime.time(nanoseconds // 1000000000, (nanoseconds // 1000000) % 1000, (nanoseconds // 1000) % 1000, tzinfo=tz)
    else:
        return datetime.time(nanoseconds // 1000000000, (nanoseconds // 1000000) % 1000, (nanoseconds // 1000) % 1000)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        return {"days": value.days, "seconds": value.seconds, "microseconds": value.microseconds}
    except AttributeError:
        raise TypeError("Invalid input type, expected timedelta") from None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    try:
        return value.isoformat()
    except AttributeError:
        raise ValueError("Invalid time value")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Value must be a Point")
    return {
        "x": value.x,
        "y": value.y,
        "z": value.z
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        return list(self.data.keys())
    except AttributeError:
        return []

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._protocol_handlers[version] for version in cls._protocol_handlers}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if protocol_version in cls._protocol_handlers:
            return {protocol_version: cls._protocol_handlers[protocol_version]}
        else:
            return {}

def index(self, key):
    try:
        return self.data.index(key)
    except ValueError:
        return -1

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.values())
    else:
        return [self.values()[key] for key in keys]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not keys:
        return self._data

    result = {}
    for key in keys:
        try:
            result[key] = self._data[key]
        except KeyError:
            result[key] = None

    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    try:
        if n == -1:
            n = self.last_query_id
        if qid == -1:
            qid = self.last_query_id
        if dehydration_hooks is None:
            dehydration_hooks = self.dehydration_hooks
        if hydration_hooks is None:
            hydration_hooks = self.hydration_hooks
        if not isinstance(n, int):
            raise TypeError("n must be an integer")
        if not isinstance(qid, int):
            raise TypeError("qid must be an integer")
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        if not all(isinstance(key, type) for key in dehydration_hooks.keys()):
            raise TypeError("dehydration_hooks keys must be types")
        if not all(isinstance(key, type) for key in hydration_hooks.keys()):
            raise TypeError("hydration_hooks keys must be types")
        if not all(callable(value) for value in dehydration_hooks.values()):
            raise TypeError("dehydration_hooks values must be callable")
        if not all(callable(value) for value in hydration_hooks.values()):
            raise TypeError("hydration_hooks values must be callable")
        if not all(isinstance(handler, type) for handler in handlers.values()):
            raise TypeError("handlers values must be types")
        if not all(issubclass(handler, Response) for handler in handlers.values()):
            raise TypeError("handlers values must be subclasses of Response")
        self.output_queue.append(
            DiscardMessage(n, qid, dehydration_hooks, hydration_hooks, **handlers)
        )
    except Exception as e:
        raise ValueError("Invalid input") from e

def round_half_to_even(n):
    """
    Round a number to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 2 == 0:
        return n
    else:
        return n + 1

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, list):
        raise TypeError("fields must be a list")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    class PointSubclass(Point):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.name = name
            self.fields = fields
            self.srid_map = srid_map

        def __repr__(self):
            return f"{self.name}({', '.join(self.fields)})"

    return PointSubclass

