def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if lock is not None:
                with lock:
                    if key(*args, **kwargs) in cache:
                        return cache[key(*args, **kwargs)]
                    result = func(*args, **kwargs)
                    cache[key(*args, **kwargs)] = result
                    return result
            else:
                if key(*args, **kwargs) in cache:
                    return cache[key(*args, **kwargs)]
                result = func(*args, **kwargs)
                cache[key(*args, **kwargs)] = result
                return result
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def wrapper(func):
        cache = {}
        def wrapped(*args, **kwargs):
            if typed:
                key = (args, tuple(kwargs.items()))
            else:
                key = (args, tuple(kwargs.values()))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result
        return wrapped
    return wrapper

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def wrapper(func):
        cache = {}
        def inner_func(*args, **kwargs):
            if typed:
                key = args + tuple(kwargs.items())
            else:
                key = args
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem()
            return result
        return inner_func
    return wrapper

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        use_count = {}

        def wrapper(*args, **kwargs):
            if typed:
                key = args[0]
            else:
                key = make_key(args, kwargs)

            if key in cache:
                use_count[key] += 1
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            use_count[key] = 1

            if len(cache) > maxsize:
                for key, _ in sorted(use_count.items(), key=lambda x: x[1]):
                    if key in cache:
                        del cache[key]
                        del use_count[key]
                        break

            return result

        return wrapper

    return decorator

