def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    # Check if the input is valid
    if not isinstance(all, bool):
        raise ValueError("The 'all' parameter must be a boolean value.")

    # Get the attribute names and descriptions defined by the interface
    attribute_names = self.__class__.getAttributeNames()
    attribute_descriptions = self.__class__.getAttributeDescriptions()

    # Return the attribute names and descriptions
    if all:
        return attribute_names, attribute_descriptions
    else:
        return attribute_names

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    try:
        if all:
            return self.__dict__.keys()
        else:
            return [key for key in self.__dict__.keys() if not key.startswith('_')]
    except AttributeError:
        return []

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, Declaration):
            output.append(item)
        elif isinstance(item, tuple):
            output.extend(_normalizeargs(item))
        else:
            raise ValueError("Invalid argument type")
    return output

