def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import platform
        if platform.python_implementation() == "PyPy":
            return False
        if os.environ.get("PURE_PYTHON", "0") == "1":
            return False
        return True
    except Exception as e:
        return False

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if self.initial_value is not None:
        self.bins = [self.initial_value] * self.num_bins
    else:
        self.bins = self.make_bins()

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins and edges must be equal.")
    if not all(isinstance(x, (int, float)) for x in bins):
        raise ValueError("Bins must be numeric.")
    if not all(isinstance(x, (int, float)) for x in edges):
        raise ValueError("Edges must be numeric.")
    if not all(edges[i] < edges[i+1] for i in range(len(edges)-1)):
        raise ValueError("Edges must be in increasing order.")

    total = 0
    for i in range(len(bins)):
        total += bins[i] * (edges[i+1] - edges[i])
    return total

def is_fill_request_el(obj):
