def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        if not hasattr(obj, 'fill') or not hasattr(obj, 'compute'):
            return False
        if not callable(obj.fill) or not callable(obj.compute):
            return False
        return True
    except:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    diff = {}
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
        elif isinstance(value, dict):
            subdiff = difference(value, d2[key], level-1)
            if subdiff:
                diff[key] = subdiff
    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("Coordinate must be a tuple of length 2")
    if not isinstance(weight, (int, float)):
        raise ValueError("Weight must be a number")
    if weight < 0:
        raise ValueError("Weight must be non-negative")

    x, y = coord
    if x < 0 or x >= self.width or y < 0 or y >= self.height:
        return

    self.data[y][x] += weight

def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    try:
        return re.compile(r"^[a-z0-9]([-a-z0-9]*[a-z0-9])?$")
    except re.error as e:
        raise ValueError("Invalid regular expression") from e

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    try:
        if not re.match(r"^[a-zA-Z0-9_]+$", value):
            raise ValidationError("Invalid value: {}".format(value))
    except ValueError:
        raise ValidationError("Invalid value: {}".format(value))

def validate_key(key):
    import re
    pattern = r"^[a-zA-Z0-9_-]{3,20}$"
    if not re.match(pattern, key):
        raise ValidationError("Invalid key: {}".format(key))
    return key

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generates a partial observer schema dictionary from a Kubernetes resource manifest dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resource manifest dictionary.
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource. Defaults to False.

    Returns:
        dict: Generated partial observer schema dictionary.
    """
    observer_schema_dict = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema_dict[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema_dict[key] = generate_default_observer_schema_list(value)
        else:
            observer_schema_dict[key] = None
    if first_level:
        observer_schema_dict["apiVersion"] = manifest_dict.get("apiVersion")
        observer_schema_dict["kind"] = manifest_dict.get("kind")
        observer_schema_dict["metadata"] = manifest_dict.get("metadata")
    return observer_schema_dict

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        elif isinstance(last_applied_manifest[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
