def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        manifest = app.spec.manifest
        for resource in manifest:
            if not resource.observer_schema:
                resource.observer_schema = generate_default_observer_schema_for_resource(resource)
    except AttributeError as e:
        raise ValueError("Invalid application object: missing required attribute") from e
    return app

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(params, (Mapping, Sequence)):
        raise TypeError("params must be a Mapping or Sequence")

    if isinstance(params, Mapping):
        in_style = self.in_style
        if in_style == "named":
            out_style = "named"
        elif in_style == "pyformat":
            out_style = "pyformat"
        elif in_style == "format":
            out_style = "format"
        else:
            raise ValueError("Unsupported in_style")

        if out_style == "named":
            out_params = {key: value for key, value in params.items()}
        elif out_style == "pyformat":
            out_params = {key: value for key, value in params.items()}
        elif out_style == "format":
            out_params = [value for key, value in params.items()]
        else:
            raise ValueError("Unsupported out_style")
    else:
        out_params = params

    return sql, out_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Check if path is a valid OCFL object
        if not self.is_ocfl_object(path):
            return False

        # Check if the OCFL object is valid
        if not self.is_valid_ocfl_object(path):
            return False

        # Check if the OCFL object is valid (warnings permitted)
        if not self.is_valid_ocfl_object_warnings_permitted(path):
            return False

        return True
    except Exception as e:
        # Handle any exceptions that may occur during validation
        self.logger.error(f"Error validating OCFL object at {path}: {e}")
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = self.status()
        if status == 'valid':
            return f'{prefix}Valid'
        elif status == 'invalid':
            return f'{prefix}Invalid'
        else:
            return f'{prefix}Unknown'
    except Exception as e:
        return f'{prefix}Error: {e}'

def status_str(self, prefix=''):
