def _group_files_by_xml_filename(xml_filename, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    try:
        xml_basename = os.path.basename(xml_filename)
        package = Package(xml_basename)
        for file in files:
            if file.endswith('.xml'):
                package.add_file(file)
        return {xml_basename: package}
    except Exception as e:
        print(f"Error occurred while grouping files by XML basename: {e}")
        return {}

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    try:
        files = os.listdir(folder)
        packages = {}
        for file in files:
            if file.endswith(".xml"):
                basename = os.path.basename(file)
                if basename not in packages:
                    packages[basename] = []
                packages[basename].append(file)
        return packages
    except OSError as e:
        print("Error:", e)
        return {}

