def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Command must be a string")
        if not isinstance(args, list):
            raise ValueError("Args must be a list")
        if cwd and not isinstance(cwd, str):
            raise ValueError("Cwd must be a string")
        if env and not isinstance(env, dict):
            raise ValueError("Env must be a dictionary")
        try:
            if verbose:
                print(f"Running command: {command} {args}")
            result = subprocess.run(command, args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            if result.returncode != 0:
                raise RuntimeError(f"Command {command} failed with exit code {result.returncode}")
            if not hide_stderr:
                print(result.stderr.decode())
            return result.stdout.decode()
        except FileNotFoundError:
            raise RuntimeError(f"Command {command} not found")
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Command {command} failed with exit code {e.returncode}")

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def wrapper(*args, **kwargs):
        try:
            method(*args, **kwargs)
        except Exception as e:
            print(f"Error handling VCS {vcs}: {e}")
    return wrapper

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for root, dirs, files in os.walk(self.storage_root):
        for file in files:
            if file.endswith('.json'):
                num_objects += 1
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r') as f:
                        data = json.load(f)
                        if validate_objects:
                            self.validate_object(data)
                        if check_digests:
                            self.check_digest(data)
                        good_objects += 1
                except json.JSONDecodeError as e:
                    if show_warnings:
                        print(f"Warning: {file_path} is not a valid JSON file.")
                except ValueError as e:
                    if show_warnings:
                        print(f"Warning: {file_path} is not a valid object.")
                except DigestMismatchError as e:
                    if show_warnings:
                        print(f"Warning: {file_path} has a digest mismatch.")
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        version_parts = version.split(".")
        if len(version_parts) != 3:
            raise ValueError("Invalid version format")
        major, minor, patch = version_parts
        if not major.isdigit() or not minor.isdigit() or not patch.isdigit():
            raise ValueError("Invalid version format")
        patch = int(patch) + 1
        return f"{major}.{minor}.{patch}"
    except ValueError as e:
        raise ValueError("Invalid version format") from e

def validate_version_inventories(self, version_dirs):
    # Check if the version directories are in sequence
    if not is_sequence(version_dirs):
        raise ValueError("Version directories must be in sequence")

    # Check if each version has an inventory
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, "inventory.json")
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory not found for version {version_dir}")

    # Check if the content digests are different from those in the root inventory
    root_inventory_path = os.path.join(version_dirs[0], "inventory.json")
    root_inventory = json.load(open(root_inventory_path))
    for version_dir in version_dirs[1:]:
        inventory_path = os.path.join(version_dir, "inventory.json")
        inventory = json.load(open(inventory_path))
        for digest in inventory["digests"]:
            if digest not in root_inventory["digests"]:
                raise ValueError(f"Digest {digest} not found in root inventory")

    return True

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if not os.path.exists(path):
            return "other: path does not exist"
        if not os.path.isdir(path):
            return "other: path is not a directory"
        if not os.path.isfile(os.path.join(path, "0=*")):
            return "other: no '0=*' Namaste file found"
        with open(os.path.join(path, "0=*"), "r") as f:
            contents = f.read()
            if "OCFL Storage Root" in contents:
                return "root"
            elif "OCFL Object" in contents:
                return "object"
            else:
                return "file"
    except Exception as e:
        return "other: " + str(e)

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    try:
        if not isinstance(params, dict):
            raise TypeError("Params must be a dictionary")
        if not isinstance(bug_ids, list):
            raise TypeError("Bug IDs must be a list")
        for bug_id in bug_ids:
            if not isinstance(bug_id, int):
                raise TypeError("Bug ID must be an integer")
            if bug_id not in params:
                raise KeyError("Bug ID not found in params")
            params[bug_id] = self.amend_bzparam(params[bug_id])
        return params
    except TypeError as e:
        print(e)
        return None
    except KeyError as e:
        print(e)
        return None

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged_nodes = []
    for node in nodes:
        key, value = node
        if isinstance(value, MappingNode):
            for sub_key, sub_value in value.value:
                if isinstance(sub_value, MappingNode):
                    for sub_sub_key, sub_sub_value in sub_value.value:
                        merged_nodes.append((sub_sub_key, sub_sub_value))
                else:
                    merged_nodes.append((sub_key, sub_value))
        else:
            merged_nodes.append((key, value))
    return merged_nodes

