def bash_completion():
    try:
        import argparse
        import borgmatic

        # Get the command-line argument parsers for borgmatic
        parser = argparse.ArgumentParser()
        subparsers = parser.add_subparsers()
        borgmatic.setup_argparse(subparsers)

        # Introspect the parsers to generate the bash completion script
        script = ""
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for subaction in action._name_parser_map.values():
                    script += f"complete -W '{subaction.choices}' {subaction.dest}\n"

        return script

    except Exception as e:
        print(f"Error generating bash completion script: {e}")
        return ""

