def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = sys.platform
    if platform == 'win32':
        return _split_windows(s)
    else:
        return _split_posix(s)

def _split_windows(s):
    # Use a regular expression to split the string into tokens,
    # treating double quotes as a special case.
    tokens = re.split(r'(\"[^\"]*\"|\S+)', s)
    # Remove any empty strings from the list.
    tokens = [token for token in tokens if token]
    # Strip the quotes from the tokens.
    tokens = [token.strip('"') for token in tokens]
    return tokens

def _split_posix(s):
    # Use a regular expression to split the string into tokens,
    # treating single quotes as a special case.
    tokens = re.split(r"('[^']*'|\S+)", s)
    # Remove any empty strings from the list.
    tokens = [token for token in tokens if token]
    # Strip the quotes from the tokens.
    tokens = [token.strip("'") for token in tokens]
    return tokens

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        num, unit = frequency.split()
        num = int(num)
        if unit == "week":
            return datetime.timedelta(weeks=num)
        elif unit == "day":
            return datetime.timedelta(days=num)
        elif unit == "hour":
            return datetime.timedelta(hours=num)
        elif unit == "minute":
            return datetime.timedelta(minutes=num)
        elif unit == "second":
            return datetime.timedelta(seconds=num)
        else:
            raise ValueError(f"Invalid unit of time: {unit}")
    except ValueError:
        raise ValueError(f"Invalid frequency: {frequency}")

