def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if isinstance(commands, str):
            commands = [commands]
        for command in commands:
            if cwd is not None:
                os.chdir(cwd)
            if env is not None:
                os.environ.update(env)
            if verbose:
                print(f"Running command: {command}")
            result = subprocess.run(command, args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            if hide_stderr:
                result.stderr = b""
            if result.returncode != 0:
                raise RuntimeError(f"Command {command} failed with exit code {result.returncode}")
            if verbose:
                print(f"Command {command} completed successfully")
        return result.stdout.decode("utf-8")
    except Exception as e:
        raise RuntimeError(f"Error running command: {e}")

