def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set()
    for base in bases:
        if hasattr(base, '__class__'):
            metaclasses.add(base.__class__)
    if len(metaclasses) == 1:
        return metaclasses.pop()
    else:
        raise TypeError("Inconsistent metaclasses found")

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    min_count = float("inf")
    min_key = None
    for key, (value, count) in self.items():
        if count < min_count:
            min_count = count
            min_key = key

    if min_key is None:
        raise KeyError("popitem(): dictionary is empty")

    value = self[min_key]
    del self[min_key]
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    oldest_key = None
    for key, _ in self.items():
        if oldest_key is None or self._order[key] < self._order[oldest_key]:
            oldest_key = key

    value = self[oldest_key]
    del self[oldest_key]
    return (oldest_key, value)

