def get_spec_defaults(self):
    # Resolve arguments' values from spec and other sources
    spec = self.spec
    args = self.args
    for arg in args:
        if arg not in spec:
            raise ValueError(f"Invalid argument: {arg}")
        value = spec[arg]
        if isinstance(value, dict):
            # Resolve nested values
            for key, val in value.items():
                if isinstance(val, dict):
                    # Recursively resolve nested values
                    value[key] = self.get_spec_defaults(val)
                elif isinstance(val, list):
                    # Resolve list values
                    value[key] = self.get_spec_list_defaults(val)
                else:
                    # Use the default value
                    value[key] = val
        else:
            # Use the default value
            value = spec[arg]
        args[arg] = value
    return args

def get_spec_list_defaults(self, values):
    # Resolve list values
    for i, value in enumerate(values):
        if isinstance(value, dict):
            # Recursively resolve nested values
            values[i] = self.get_spec_defaults(value)
        else:
            # Use the default value
            values[i] = value
    return values

